export interface ConnectorConfig {
  /** Twilio Auth Token from TWILIO_AUTH_TOKEN env var, used to validate X-Twilio-Signature */
  twilioAuthToken: string
  /** Slack Bot Token from SLACK_BOT_TOKEN env var, used as Bearer token for chat.postMessage */
  slackBotToken: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
  /** Optional: full webhook URL as registered in Twilio Console (for signature validation) */
  twilioWebhookUrl?: string
  /** Optional: raw request body as received (for signature validation) */
  twilioRawBody?: string
  /** Optional: X-Twilio-Signature header value (for signature validation) */
  twilioSignature?: string
}

export interface TwilioIncomingSmsPayload {
  MessageSid: string
  AccountSid: string
  From: string
  To: string
  Body: string
  NumMedia: string
  NumSegments: string
  [key: string]: string
}

export interface HandleResult {
  slackMessageTs: string
  slackChannelId: string
  slackChannelName: string
  routedTo: 'sales' | 'support'
}

const SALES_KEYWORDS = /pricing|quote|demo/i

function validateRequiredFields(payload: TwilioIncomingSmsPayload): void {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }
}

function validateTwilioSignature(config: ConnectorConfig): void {
  const { twilioAuthToken, twilioWebhookUrl, twilioRawBody, twilioSignature } = config
  if (!twilioWebhookUrl || !twilioRawBody || !twilioSignature) {
    return
  }
  const crypto = require('crypto')
  const expectedSignature = crypto
    .createHmac('sha1', twilioAuthToken)
    .update(twilioWebhookUrl + twilioRawBody)
    .digest('base64')
  if (expectedSignature !== twilioSignature) {
    throw new Error('Invalid Twilio signature')
  }
}

function determineChannel(body: string): { channel: string; routedTo: 'sales' | 'support' } {
  if (SALES_KEYWORDS.test(body)) {
    return { channel: '#sales', routedTo: 'sales' }
  }
  return { channel: '#support', routedTo: 'support' }
}

async function postToSlack(
  channel: string,
  text: string,
  slackBotToken: string,
  fetchFn: typeof fetch,
): Promise<{ ts: string; channel: string }> {
  const response = await fetchFn('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ channel, text }),
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string }
  if (!data.ok) {
    throw new Error('Slack API returned ok: false')
  }
  return { ts: data.ts, channel: data.channel }
}

export async function handle(
  payload: TwilioIncomingSmsPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  validateRequiredFields(payload)
  validateTwilioSignature(config)

  const { channel, routedTo } = determineChannel(payload.Body)

  const { ts, channel: channelId } = await postToSlack(
    channel,
    payload.Body,
    config.slackBotToken,
    config.fetch ?? fetch,
  )

  return {
    slackMessageTs: ts,
    slackChannelId: channelId,
    slackChannelName: channel,
    routedTo,
  }
}

