    const fake = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' }, 200)
      }
