    expect(result.routedTo).toBe('sales')
    expect(result.slackChannelName).toBe('#sales')
    expect(calls[0].json).toEqual({ channel: '#sales', text: payload.Body })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-slack-token')
  })

  it('routes to #sales when body contains quote (case insensitive)', async () => {
    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Please send me a QUOTE for 50 seats',
    }
    const result = await handle(payload, baseConfig)
    expect(result.routedTo).toBe('sales')
    expect(result.slackChannelName).toBe('#sales')
  })

  it('routes to #sales when body contains demo', async () => {
    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Can I schedule a demo?',
    }
    const result = await handle(payload, baseConfig)
    expect(result.routedTo).toBe('sales')
    expect(result.slackChannelName).toBe('#sales')
  })

  it('routes to #support when body has no sales keywords', async () => {
    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Hello, I have a question about my invoice',
    }
    const result = await handle(payload, baseConfig)
    expect(result.routedTo).toBe('support')
    expect(result.slackChannelName).toBe('#support')
    expect(calls[0].json).toEqual({ channel: '#support', text: payload.Body })
  })

  it('throws when Body is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, Body: '' } as TwilioIncomingSmsPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: Body')
  })

  it('throws when From is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, From: '' } as TwilioIncomingSmsPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: From')
  })

  it('throws on non-2xx Slack response', async () => {
    const fake = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    const config = { ...baseConfig, fetch: fake.fetch }
    const payload: TwilioIncomingSmsPayload = { ...SOURCE_EXAMPLE, Body: 'test' }
    await expect(handle(payload, config)).rejects.toThrow('Slack API error: 401 Unauthorized at POST https://slack.com/api/chat.postMessage')
  })

  it('validates Twilio signature when all params provided', async () => {
    const crypto = require('crypto')
    const webhookUrl = 'https://example.com/twilio/webhook'
    const rawBody = 'Body=Test+message&From=%2B15551234567'
    const signature = crypto.createHmac('sha1', 'test-twilio-token').update(webhookUrl + rawBody).digest('base64')

    const config: ConnectorConfig = {
      ...baseConfig,
      twilioWebhookUrl: webhookUrl,
      twilioRawBody: rawBody,
      twilioSignature: signature,
    }
    const payload: TwilioIncomingSmsPayload = { ...SOURCE_EXAMPLE, Body: 'Test message' }
    const result = await handle(payload, config)
    expect(result.routedTo).toBe('support')
  })

  it('throws on invalid Twilio signature', async () => {
    const config: ConnectorConfig = {
      ...baseConfig,
      twilioWebhookUrl: 'https://example.com/twilio/webhook',
      twilioRawBody: 'Body=Test',
      twilioSignature: 'invalid-signature',
    }
    const payload: TwilioIncomingSmsPayload = { ...SOURCE_EXAMPLE, Body: 'Test' }
    await expect(handle(payload, config)).rejects.toThrow('Invalid Twilio signature')
  })

  it('skips signature validation when params incomplete', async () => {
    const config: ConnectorConfig = {
      ...baseConfig,
      twilioWebhookUrl: 'https://example.com/twilio/webhook',
      // missing twilioRawBody and twilioSignature
    }
    const payload: TwilioIncomingSmsPayload = { ...SOURCE_EXAMPLE, Body: 'Test' }
    const result = await handle(payload, config)
    expect(result.routedTo).toBe('support')
  })

  it('returns slack message ts and channel id', async () => {
    const payload: TwilioIncomingSmsPayload = { ...SOURCE_EXAMPLE, Body: 'pricing request' }
    const result = await handle(payload, baseConfig)
    expect(result.slackMessageTs).toBe('1234567890.123456')
    expect(result.slackChannelId).toBe('C01234567')
  })
})

